static void reveal(QWidget *w) {
 require(w,"Frame-state control missing");for(auto *p=w;p;p=p->parentWidget()) {
  for(auto *tabs:w->window()->findChildren<QTabWidget *>())if(tabs->indexOf(p)>=0)tabs->setCurrentWidget(p);
  if(auto *scroll=qobject_cast<QScrollArea *>(p))scroll->ensureWidgetVisible(w);
 }events();require(w->isVisible()&&w->isEnabled(),"Frame-state control unreachable");
}
struct Field {QLineEdit *edit;QString unit;};
static Field field(QWidget *panel,const QString &name) {
 Field found{};int count=0;
 for(auto *form:panel->findChildren<QFormLayout *>())for(int row=0;row<form->rowCount();++row) {
  auto *l=form->itemAt(row,QFormLayout::LabelRole),*f=form->itemAt(row,QFormLayout::FieldRole);auto *label=l?qobject_cast<QLabel *>(l->widget()):nullptr;auto *value=f?f->widget():nullptr;
  if(!label||label->text()!=name||!value||!value->isVisible())continue;auto *edit=qobject_cast<QLineEdit *>(value);if(!edit)edit=value->findChild<QLineEdit *>();if(!edit||edit->isReadOnly())continue;
  QString unit;for(auto *t:value->findChildren<QLabel *>(QString(),Qt::FindDirectChildrenOnly))if(t->isVisible())unit+=t->text();found={edit,unit};++count;
 }require(count==1,"Frame-state field missing/ambiguous");return found;
}
static QJsonObject graph() {
 QJsonObject result;auto *m=Moderator::Instance();for(const auto &name:m->GetListOfObjects(Gmat::UNKNOWN_OBJECT))if(auto *o=m->GetConfiguredObject(name))result[QString::fromStdString(name)]=QString::fromStdString(o->GetGeneratingString(Gmat::SCRIPTING));return result;
}
static void choose(QComboBox *combo,const QString &value) {
 reveal(combo);require(combo->findText(value)>=0,"Required state/frame choice missing");combo->showPopup();events();require(combo->view()->isVisible(),"Frame-state popup not exposed");combo->setCurrentText(value);QTest::keyClick(combo->view(),Qt::Key_Return);events();if(combo->currentText()!=value){auto *status=combo->window()->findChild<QLabel *>("resourceStatus");std::cerr<<"FRAME_STATE_CHOICE_REJECT "<<(status?status->text().toStdString():"no-status")<<std::endl;}require(combo->currentText()==value&&!combo->view()->isVisible(),"Frame-state popup delivery failed");
}
static QJsonArray conic(const QJsonArray &k,double mu) {
 const double a=k[0].toDouble(),e=k[1].toDouble(),rad=std::acos(-1.)/180,i=k[2].toDouble()*rad,n=k[3].toDouble()*rad,w=k[4].toDouble()*rad,v=k[5].toDouble()*rad;
 const std::array<double,3> P{std::cos(n)*std::cos(w)-std::sin(n)*std::sin(w)*std::cos(i),std::sin(n)*std::cos(w)+std::cos(n)*std::sin(w)*std::cos(i),std::sin(w)*std::sin(i)},Q{-std::cos(n)*std::sin(w)-std::sin(n)*std::cos(w)*std::cos(i),-std::sin(n)*std::sin(w)+std::cos(n)*std::cos(w)*std::cos(i),std::cos(w)*std::sin(i)};
 const double p=a*(1-e*e),r=p/(1+e*std::cos(v)),scale=std::sqrt(mu/p);require(p>0&&r>0&&std::isfinite(scale),"Invalid independent conic geometry");QJsonArray result;for(int j=0;j<3;++j)result.append(r*(P[j]*std::cos(v)+Q[j]*std::sin(v)));for(int j=0;j<3;++j)result.append(scale*(-P[j]*std::sin(v)+Q[j]*(e+std::cos(v))));return result;
}
